import React, { useState, useEffect } from 'react';
import { fetchDueBills, fetchOverdueBills } from '../api/sales';
import { useAuth } from '../context/AuthContext';

const CreditBillsPage = () => {
  const { currentUser, logout } = useAuth();
  const [dueBills, setDueBills] = useState([]);
  const [overdueBills, setOverdueBills] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchBills();
  }, []);

  const fetchBills = async () => {
    setLoading(true);
    setError('');
    try {
      const [due, overdue] = await Promise.all([
        fetchDueBills(),
        fetchOverdueBills()
      ]);
      setDueBills(due);
      setOverdueBills(overdue);
    } catch (err) {
      console.error('Error fetching credit bills:', err);
      setError('Failed to load credit bills. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const calculateDaysOverdue = (dueDate) => {
    const today = new Date();
    const due = new Date(dueDate);
    const diffTime = today - due;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays > 0 ? diffDays : 0;
  };

  const calculateDaysUntilDue = (dueDate) => {
    const today = new Date();
    const due = new Date(dueDate);
    const diffTime = due - today;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays > 0 ? diffDays : 0;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex justify-center items-center">
        <div className="text-xl">Loading credit bills...</div>
      </div>
    );
  }

  const totalDueAmount = dueBills.reduce((sum, bill) => sum + (bill.totalAmount || 0), 0);
  const totalOverdueAmount = overdueBills.reduce((sum, bill) => sum + (bill.totalAmount || 0), 0);
  const totalOutstanding = totalDueAmount + totalOverdueAmount;

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <nav className="bg-white shadow">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <h1 className="text-2xl font-bold text-gray-900">Credit Bills Management</h1>
            <div className="flex items-center space-x-4">
              <span className="text-gray-700">Welcome, {currentUser?.username}</span>
              <button
                onClick={logout}
                className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-md text-sm font-medium"
              >
                Logout
              </button>
            </div>
          </div>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        <div className="px-4 py-6 sm:px-0">
          {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-6">
              {error}
            </div>
          )}

          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
            <div className="bg-white overflow-hidden shadow rounded-lg">
              <div className="p-5">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <div className="h-10 w-10 bg-yellow-500 rounded-full flex items-center justify-center text-white text-xl">
                      📅
                    </div>
                  </div>
                  <div className="ml-5">
                    <dt className="text-sm font-medium text-gray-500">Due Soon</dt>
                    <dd className="text-2xl font-bold text-gray-900">{dueBills.length} bills</dd>
                    <dd className="text-sm text-gray-500">${totalDueAmount.toFixed(2)}</dd>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-white overflow-hidden shadow rounded-lg">
              <div className="p-5">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <div className="h-10 w-10 bg-red-500 rounded-full flex items-center justify-center text-white text-xl">
                      ⚠️
                    </div>
                  </div>
                  <div className="ml-5">
                    <dt className="text-sm font-medium text-gray-500">Overdue</dt>
                    <dd className="text-2xl font-bold text-red-900">{overdueBills.length} bills</dd>
                    <dd className="text-sm text-red-500">${totalOverdueAmount.toFixed(2)}</dd>
                  </div>
                </div>
              </div>
            </div>
            <div className="bg-white overflow-hidden shadow rounded-lg">
              <div className="p-5">
                <div className="flex items-center">
                  <div className="flex-shrink-0">
                    <div className="h-10 w-10 bg-blue-500 rounded-full flex items-center justify-center text-white text-xl">
                      💰
                    </div>
                  </div>
                  <div className="ml-5">
                    <dt className="text-sm font-medium text-gray-500">Total Outstanding</dt>
                    <dd className="text-2xl font-bold text-gray-900">${totalOutstanding.toFixed(2)}</dd>
                    <dd className="text-sm text-gray-500">{(dueBills.length + overdueBills.length)} total bills</dd>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Overdue Bills Section */}
          <div className="bg-white shadow rounded-lg mb-8 overflow-hidden">
            <div className="px-6 py-4 bg-red-50 border-b border-red-200">
              <h2 className="text-xl font-semibold text-red-900">
                Overdue Bills ({overdueBills.length})
              </h2>
            </div>
            <div className="overflow-x-auto">
              {overdueBills.length === 0 ? (
                <div className="p-6 text-center text-gray-500">
                  No overdue bills. Great job!
                </div>
              ) : (
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-red-100">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-red-700 uppercase tracking-wider">
                        Customer
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-red-700 uppercase tracking-wider">
                        Amount
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-red-700 uppercase tracking-wider">
                        Due Date
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-red-700 uppercase tracking-wider">
                        Days Overdue
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {overdueBills.map((bill) => {
                      const daysOverdue = calculateDaysOverdue(bill.dueDate);
                      return (
                        <tr key={bill._id} className="hover:bg-red-50">
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-red-900">
                            {bill.customerName || 'N/A'}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-red-700">
                            ${(bill.totalAmount || 0).toFixed(2)}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-red-700">
                            {new Date(bill.dueDate).toLocaleDateString()}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className="px-2 py-1 text-xs font-semibold rounded-full bg-red-200 text-red-900">
                              {daysOverdue} day{daysOverdue !== 1 ? 's' : ''}
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              )}
            </div>
          </div>

          {/* Due Bills Section */}
          <div className="bg-white shadow rounded-lg overflow-hidden">
            <div className="px-6 py-4 bg-yellow-50 border-b border-yellow-200">
              <h2 className="text-xl font-semibold text-yellow-900">
                Due Soon ({dueBills.length})
              </h2>
            </div>
            <div className="overflow-x-auto">
              {dueBills.length === 0 ? (
                <div className="p-6 text-center text-gray-500">
                  No bills due soon.
                </div>
              ) : (
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-yellow-100">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-yellow-700 uppercase tracking-wider">
                        Customer
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-yellow-700 uppercase tracking-wider">
                        Amount
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-yellow-700 uppercase tracking-wider">
                        Due Date
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-yellow-700 uppercase tracking-wider">
                        Days Until Due
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {dueBills.map((bill) => {
                      const daysUntilDue = calculateDaysUntilDue(bill.dueDate);
                      return (
                        <tr key={bill._id} className="hover:bg-yellow-50">
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-yellow-900">
                            {bill.customerName || 'N/A'}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-yellow-700">
                            ${(bill.totalAmount || 0).toFixed(2)}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-yellow-700">
                            {new Date(bill.dueDate).toLocaleDateString()}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className="px-2 py-1 text-xs font-semibold rounded-full bg-yellow-200 text-yellow-900">
                              {daysUntilDue} day{daysUntilDue !== 1 ? 's' : ''}
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CreditBillsPage;
